// Une sortie par agence (pour interroger la file de chacune).
const data = $input.first().json;
const agences = data.content || data || [];
return agences.map(a => ({ json: { agenceId: a.id, agenceNom: a.nom } }));

// Pour chaque agence, détecte les tickets en dépassement SLA et construit le message.
// Ne sort QUE les agences ayant au moins un ticket en retard.
const agences = $('Extraire agences').all();
const queues = $input.all();
const now = Date.now();
const SLA_MIN = 120;

const out = [];
agences.forEach((a, i) => {
  const aj = a.json;
  const qj = (queues[i] || {}).json || {};
  const tickets = qj.tickets || [];
  const overdue = tickets.filter(t => t.createdAt && (now - new Date(t.createdAt).getTime()) / 60000 > SLA_MIN);
  if (overdue.length === 0) return;
  const lines = overdue.map(t => {
    const mins = Math.round((now - new Date(t.createdAt).getTime()) / 60000);
    return `• ${t.ticketNumero || 'N/A'} — ${t.clientNom || 'client'} (${t.canal || '?'}) — ${mins} min`;
  }).join('\n');
  const message = `⚠️ *Alerte SLA — ${aj.agenceNom}*\n${overdue.length} ticket(s) en attente depuis plus de ${SLA_MIN} min :\n\n${lines}\n\n👉 Merci de les prendre en charge rapidement.`;
  out.push({ json: { agence: aj.agenceNom, message } });
});
return out;
